import { promises as fs } from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";

// Resolve the data file relative to the project root (two levels up from this
// file: app/lib -> app -> project root). This keeps storage working in both
// `next dev` and `next start`.
const PROJECT_ROOT = path.resolve(
  path.dirname(new URL(import.meta.url).pathname),
  "..",
  "..",
);
const DATA_DIR = path.join(PROJECT_ROOT, "data");
const DATA_FILE = path.join(DATA_DIR, "books.json");

/** @typedef {{id: string; title: string; author: string; notes: string; finished: boolean; addedAt: string; finishedAt?: string | null}} Book */

/**
 * @returns {Promise<Book[]>}
 */
export async function getBooks() {
  try {
    const raw = await fs.readFile(DATA_FILE, "utf8");
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (err) {
    if (err && err.code === "ENOENT") return [];
    throw err;
  }
}

/**
 * @param {Book[]} books
 */
async function saveBooks(books) {
  await fs.mkdir(DATA_DIR, { recursive: true });
  const tmp = `${DATA_FILE}.${process.pid}.tmp`;
  await fs.writeFile(tmp, JSON.stringify(books, null, 2), "utf8");
  await fs.rename(tmp, DATA_FILE);
}

/**
 * @param {{title: string; author: string; notes?: string}} input
 * @returns {Promise<Book>}
 */
export async function addBook(input) {
  const books = await getBooks();
  /** @type {Book} */
  const book = {
    id: randomUUID(),
    title: input.title.trim(),
    author: input.author.trim(),
    notes: (input.notes ?? "").trim(),
    finished: false,
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.push(book);
  await saveBooks(books);
  return book;
}

/**
 * @param {string} id
 * @returns {Promise<Book | null>}
 */
export async function getBook(id) {
  const books = await getBooks();
  return books.find((b) => b.id === id) ?? null;
}

/**
 * @param {string} id
 * @returns {Promise<Book | null>}
 */
export async function markFinished(id) {
  const books = await getBooks();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.finished = true;
  book.finishedAt = new Date().toISOString();
  await saveBooks(books);
  return book;
}

/**
 * @param {string} id
 * @param {{notes?: string}} patch
 * @returns {Promise<Book | null>}
 */
export async function updateBook(id, patch) {
  const books = await getBooks();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  if (typeof patch.notes === "string") book.notes = patch.notes.trim();
  await saveBooks(books);
  return book;
}

