import { getBooks } from "./lib/books";

export const dynamic = "force-dynamic";

function BookCard({ book }) {
  return (
    <a
      href={`/books/${book.id}`}
      className="block rounded-lg border border-stone-200 bg-white p-4 shadow-sm transition hover:border-stone-300 hover:shadow"
    >
      <div className="font-medium text-stone-900">{book.title}</div>
      <div className="text-sm text-stone-500">{book.author}</div>
    </a>
  );
}

export default async function Home() {
  const books = await getBooks();
  const reading = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);

  return (
    <div className="space-y-10">
      <section>
        <div className="mb-4 flex items-center justify-between">
          <h2 className="text-lg font-semibold text-stone-900">
            Currently reading
          </h2>
          <a
            href="/books/new"
            className="rounded-md bg-stone-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-stone-700"
          >
            Add a book
          </a>
        </div>
        {reading.length === 0 ? (
          <p className="text-sm text-stone-500">
            Nothing in progress yet. Add a book to get started.
          </p>
        ) : (
          <div className="grid gap-3">
            {reading.map((book) => (
              <BookCard key={book.id} book={book} />
            ))}
          </div>
        )}
      </section>

      <section>
        <h2 className="mb-4 text-lg font-semibold text-stone-900">Finished</h2>
        {finished.length === 0 ? (
          <p className="text-sm text-stone-500">
            No finished books yet. Mark one as finished from its page.
          </p>
        ) : (
          <div className="grid gap-3">
            {finished.map((book) => (
              <BookCard key={book.id} book={book} />
            ))}
          </div>
        )}
      </section>
    </div>
  );
}

